type Order = { id: string; total: number; items?: any[] }

// Version A: plugin pipeline prepared now
interface Formatter { format(o: Order): string }
class PluginFormatter implements Formatter {
  plugins: ((s: string) => string)[] = []
  format(o: Order) { return this.plugins.reduce((s, p) => p(s), JSON.stringify(o)) }
}

// Version B: minimal serializer for current requirements
function serializeOrder(o: Order): string {
  return JSON.stringify({ id: o.id, total: o.total })
}
